{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol, a lipophilic prenylated chromanol with a long isoprenoid tail, has poor oral bioavailability in humans; this is the closest structural analog to the query's polyprenyl quinone and supports low systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lycopene, a long polyisoprenoid carotenoid, showed only 0.17% systemic availability after oral tomato paste intake, illustrating that large highly lipophilic isoprenoid molecules are often poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Synthetic lycopene dispersed in oil gave only about 1.2% systemic availability in humans, reinforcing the poor absorption of large polyisoprenoid lipids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Phytoene showed high bioavailability (58%) in humans, but its acyclic, less polar carotenoid structure and different absorption behavior limit transferability to the quinone-containing query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hyperforin, a polyprenylated phloroglucinol, showed high oral bioavailability, but its smaller size and different polar core make it a weaker analog for the large ubiquinone-like query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a ubiquinone (CoQ9-like) with a long polyprenyl tail and highly lipophilic character. Closest transferable evidence from tocotrienol and lycopene indicates poor oral systemic availability, and known CoQ10 behavior is consistent with low F (<20%). High-bioavailability analogs such as phytoene and hyperforin are structurally less transferable.",
  "evidence_gaps": [
    "No direct experimental record for ubiquinone/CoQ9 absolute oral bioavailability is present in the evidence set.",
    "The query-specific identity is inferred as a ubiquinone homolog; no explicit query label or prior is supplied.",
    "Formulation effects are not captured; some ubiquinone formulations can improve absorption, but the threshold question concerns the molecule itself."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
