      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "polyisoprenoid carotenoids"
    },
    {
      "applicability": "low",
      "card_ids": ["C14"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "carotenoid precursors"
    },
    {
      "applicability": "low",
